import { Instrument, InstArgs } from "./instruments"
import {
  init as initMidi,
  getOutputs,
  onOutputsChanged,
  offOutputsChanged,
  audioTimeToMidiTime,
} from "./midi_manager"
import { beat_to_context_time, context_time_to_beat } from "./loop_manager"

const NOTE_OFF = 0x80
const NOTE_ON = 0x90
const CC = 0xb0
const CLOCK = 0xf8
const START = 0xfa
const STOP = 0xfc

const ALL_NOTES_OFF = 123

const PPQN = 24 //MIDI clock ticks per quarter note. Fixed by the spec, not a preference

/*
 * How far ahead of the audio clock ticks get queued, and how often we wake to refill.
 *
 * Accuracy doesn't come from either of these -- it comes from the timestamps -- so the
 * window can be as wide as we like, and a wide one means far fewer main-thread wakeups.
 * A second of lookahead is ~48 queued messages at 120bpm and two wakeups a second, next
 * to forty at the 100ms it takes to be tempo-agile.
 *
 * We can afford that only because bpm is fixed for the life of a track: queued ticks go
 * out at whatever tempo they were queued at, and the escape hatch, output.clear(), would
 * drop pending note-offs sitting in the same queue. What the width does still cost is
 * stop latency -- see stopClock.
 *
 * Refill at half the window so a single missed wakeup can't drain it.
 */
const LOOKAHEAD_S = 1.0
const PUMP_INTERVAL_MS = (LOOKAHEAD_S * 1000) / 2

//Runway to get Start out ahead of the first tick. Deliberately not LOOKAHEAD_S: how wide
//the queue is has nothing to do with how soon we can begin filling it, and tying the two
//together would make widening the window delay the downbeat too.
const ARM_S = 0.05

const VELOCITY = 100 //audio.ts drops velocity before it reaches play(), so pick one

/*
 * Sends MIDI out: clock, transport and notes.
 *
 * Nothing here tries to hit a moment in real time. Every message is handed to
 * output.send() with a timestamp and dispatched by the browser below the main thread, so
 * a garbage collection or a Janet reload costs us nothing as long as we refill the queue
 * more often than LOOKAHEAD_S. That is what makes the clock steady enough to slave gear
 * to -- at 120bpm a tick is only 20.8ms apart, and main-thread jitter alone would swamp
 * it.
 */
class MIDIInst extends Instrument {
  static def = { name: "midi" }

  channel = 0 //0-15 on the wire, presented as 1-16 in the DSL
  output: MIDIOutput
  clockRunning = false
  nextTick = 0 //ticks since the start of the master timeline; the first one not yet queued
  pumpTimer: number

  settingsEl: HTMLElement
  enableEl: HTMLButtonElement
  outputSelectEl: HTMLSelectElement
  clockButtonEl: HTMLButtonElement

  constructor(context: AudioContext, parentEl: Element, name: string) {
    super(context, parentEl, name)
    //no inputNode or outputNode: this makes sound somewhere else entirely, so wiring it
    //to anything should error :)
    this.setupUI()
  }

  async setup({ channel }: InstArgs) {
    const parsed = parseInt(channel)
    this.channel = Number.isNaN(parsed) ? 0 : Math.min(15, Math.max(0, parsed - 1))
    return this
  }

  // --- transport -------------------------------------------------------------

  toggleClock() {
    if (this.clockRunning) {
      this.stopClock()
    } else {
      this.startClock()
    }
  }

  startClock() {
    if (!this.output || this.clockRunning) {
      return
    }
    //Start on the next whole beat, so a slaved device's downbeat lands on one of ours
    const startBeat = Math.ceil(
      context_time_to_beat(this.audioContext.currentTime + ARM_S),
    )
    const startTime = beat_to_context_time(startBeat)

    this.nextTick = startBeat * PPQN
    this.clockRunning = true
    //A hair before the first tick: ordering of same-timestamp messages isn't worth relying on
    this.output.send(
      [START],
      audioTimeToMidiTime(this.audioContext, startTime) - 1,
    )
    this.pump()
    this.renderClock()
  }

  stopClock() {
    if (!this.clockRunning) {
      return
    }
    this.clockRunning = false
    window.clearTimeout(this.pumpTimer)
    //Ticks out to the lookahead horizon are already queued, so land Stop just after the
    //last of them. output.clear() would stop dead, but it would also drop any note-offs
    //waiting in the same queue, and a hardware synth left holding a note is worse than a
    //device that keeps ticking for the rest of the window. This is what a wide
    //LOOKAHEAD_S costs, and the reason not to widen it much further.
    this.output?.send(
      [STOP],
      audioTimeToMidiTime(this.audioContext, beat_to_context_time(this.nextTick / PPQN)),
    )
    this.renderClock()
  }

  pump = () => {
    if (!this.clockRunning || !this.output) {
      return
    }
    const horizon = this.audioContext.currentTime + LOOKAHEAD_S
    let at = beat_to_context_time(this.nextTick / PPQN)
    while (at < horizon) {
      //Skip rather than send ticks that are already in the past: a stalled tab (or a
      //throttled background one) would otherwise come back and dump thousands of them at
      //the device at once. Dropping them silently re-syncs to the grid instead.
      if (at >= this.audioContext.currentTime) {
        this.output.send([CLOCK], audioTimeToMidiTime(this.audioContext, at))
      }
      this.nextTick += 1
      at = beat_to_context_time(this.nextTick / PPQN)
    }
    this.pumpTimer = window.setTimeout(this.pump, PUMP_INTERVAL_MS)
  }

  // --- notes -----------------------------------------------------------------

  //seconds. dur === 0 means noteOff, dur < 0 means noteOn, else play for the duration
  play(note, startTime, dur) {
    if (!this.output) {
      return
    }
    const at = audioTimeToMidiTime(this.audioContext, startTime)
    if (dur === 0) {
      this.output.send([NOTE_OFF | this.channel, note, 0], at)
      return
    }
    this.output.send([NOTE_ON | this.channel, note, VELOCITY], at)
    if (dur > 0) {
      this.output.send(
        [NOTE_OFF | this.channel, note, 0],
        audioTimeToMidiTime(this.audioContext, startTime + dur),
      )
    }
  }

  // --- ui --------------------------------------------------------------------

  setupUI() {
    this.settingsEl = document.createElement("div")
    this.settingsEl.className = "settings"
    this.el.appendChild(this.settingsEl)

    this.enableEl = document.createElement("button")
    this.enableEl.className = "midi-button"
    this.enableEl.innerText = "enable midi out"
    //Asking for MIDI access prompts the user, and every script gets a :midi instrument
    //whether it wanted one or not, so wait to be asked
    this.enableEl.addEventListener("click", () => this.enable())

    this.outputSelectEl = document.createElement("select")
    this.outputSelectEl.className = "midi-select"
    this.outputSelectEl.addEventListener("change", () =>
      this.selectOutput(this.outputSelectEl.value),
    )

    this.clockButtonEl = document.createElement("button")
    this.clockButtonEl.className = "midi-button"
    this.clockButtonEl.addEventListener("click", () => this.toggleClock())

    this.settingsEl.appendChild(this.enableEl)
  }

  async enable() {
    if (!(await initMidi())) {
      this.enableEl.innerText = "midi unavailable"
      return
    }
    this.settingsEl.replaceChildren(this.outputSelectEl, this.clockButtonEl)
    onOutputsChanged(this.refreshOutputs)
    this.refreshOutputs()
  }

  refreshOutputs = () => {
    const outputs = getOutputs()
    const selectedId = this.output?.id

    this.outputSelectEl.replaceChildren(
      ...[
        { id: "", label: "-- no output --" },
        ...outputs.map((output) => ({
          id: output.id,
          label: output.name ?? output.id,
        })),
      ].map(({ id, label }) => {
        const optionEl = document.createElement("option")
        optionEl.value = id
        optionEl.innerText = label
        return optionEl
      }),
    )

    //Hold onto the current device across a replug, if it came back
    const stillThere = outputs.some((output) => output.id === selectedId)
    this.outputSelectEl.value = stillThere ? selectedId : ""
    this.selectOutput(this.outputSelectEl.value)
  }

  selectOutput(id: string) {
    const next = getOutputs().find((output) => output.id === id)
    if (next === this.output) {
      return
    }
    this.stopClock() //tell the old device we're done before we walk away from it
    this.output = next
    this.renderClock()
  }

  renderClock = () => {
    this.clockButtonEl.innerText = `clock: ${this.clockRunning ? "on" : "off"}`
    this.clockButtonEl.classList.toggle("running", this.clockRunning)
    this.clockButtonEl.disabled = !this.output
  }

  disconnect() {
    this.stopClock()
    //Leaving a hardware synth with notes held down is a bad way to end a set
    this.output?.send([CC | this.channel, ALL_NOTES_OFF, 0])
    offOutputsChanged(this.refreshOutputs)
    super.disconnect()
  }
}

export { MIDIInst }
