/**
 * Minimal RIFF reader. SF2 files are RIFF containers, so everything the parser
 * needs is "walk a flat run of `<4cc><u32 size><payload>` records".
 */

export type Chunk = {
  readonly id: string
  readonly data: DataView
}

export type List = {
  readonly type: string
  readonly chunks: readonly Chunk[]
}

const fourCC = (view: DataView, at: number): string =>
  String.fromCharCode(
    view.getUint8(at),
    view.getUint8(at + 1),
    view.getUint8(at + 2),
    view.getUint8(at + 3),
  )

const subView = (view: DataView, at: number, size: number): DataView =>
  new DataView(view.buffer, view.byteOffset + at, size)

/** Chunks laid out back to back inside `view`, in file order. */
export const readChunks = (view: DataView): readonly Chunk[] => {
  const out: Chunk[] = []
  for (let at = 0; at + 8 <= view.byteLength; ) {
    const id = fourCC(view, at)
    const size = view.getUint32(at + 4, true)
    if (at + 8 + size > view.byteLength) throw new Error(`truncated RIFF chunk "${id}"`)
    out.push({ id, data: subView(view, at + 8, size) })
    at += 8 + size + (size & 1) // records are word aligned
  }
  return out
}

/** Read a `RIFF`/`LIST` chunk: a 4cc form type followed by nested chunks. */
export const readList = (chunk: Chunk): List => ({
  type: fourCC(chunk.data, 0),
  chunks: readChunks(subView(chunk.data, 4, chunk.data.byteLength - 4)),
})

/**
 * Read a whole RIFF file, asserting its form type (e.g. `sfbk`). The declared
 * size is clamped to what is actually there: files in the wild routinely
 * overstate it, and the chunk walk below catches any genuine truncation.
 */
export const readRiff = (buffer: ArrayBuffer, expectedType: string): List => {
  const view = new DataView(buffer)
  if (view.byteLength < 12 || fourCC(view, 0) !== 'RIFF') throw new Error('not a RIFF file')
  const declared = view.getUint32(4, true)
  const body = subView(view, 8, Math.min(declared, view.byteLength - 8))
  const type = fourCC(body, 0)
  if (type !== expectedType) {
    throw new Error(`expected a "${expectedType}" RIFF file, got "${type}"`)
  }
  return { type, chunks: readChunks(subView(body, 4, body.byteLength - 4)) }
}

export const findChunk = (chunks: readonly Chunk[], id: string): Chunk | undefined =>
  chunks.find((c) => c.id === id)

export const requireChunk = (chunks: readonly Chunk[], id: string): Chunk => {
  const chunk = findChunk(chunks, id)
  if (!chunk) throw new Error(`missing required chunk "${id}"`)
  return chunk
}

export const findList = (chunks: readonly Chunk[], type: string): List => {
  const list = chunks.filter((c) => c.id === 'LIST').map(readList).find((l) => l.type === type)
  if (!list) throw new Error(`missing required LIST "${type}"`)
  return list
}

/** Fixed-width, NUL-padded ASCII field. */
export const readName = (view: DataView, at: number, length: number): string => {
  const bytes: number[] = []
  for (let i = 0; i < length; i++) {
    const b = view.getUint8(at + i)
    if (b === 0) break
    bytes.push(b)
  }
  return String.fromCharCode(...bytes).trimEnd()
}

/** Split a chunk into `count` fixed-size records and map each one. */
export const readRecords = <T>(chunk: Chunk, size: number, read: (view: DataView) => T): T[] => {
  const count = Math.floor(chunk.data.byteLength / size)
  return Array.from({ length: count }, (_, i) => read(subView(chunk.data, i * size, size)))
}
