/**
 * SF2 modulators, restricted to the ones that fire at note-on.
 *
 * A modulator routes a controller through a transfer curve and adds the result
 * to a generator. Sources split into two kinds: note-on values (velocity, key
 * number), which are known the instant a voice starts, and MIDI controllers
 * (mod wheel, aftertouch, pitch wheel), which change while a note sounds.
 *
 * Only the note-on kind is applied here, because only that kind changes how a
 * note sounds in the absence of a live controller feed. Surveying real sound
 * fonts, the controller-sourced modulators they ship are inert at rest anyway:
 * they sit at zero amount, or their controller's resting value maps to zero.
 */

import { isAdditiveGen, signedGen } from './generators.js'
import type { GenMap } from './generators.js'

export type Modulator = {
  /** `sfModSrcOper`: index, CC flag, direction, polarity and curve type. */
  readonly source: number
  /** `sfModDestOper`: a generator, or a link to another modulator. */
  readonly destination: number
  readonly amount: number
  readonly amountSource: number
  readonly transform: number
}

const VELOCITY = 2
const KEY_NUMBER = 3

const index = (op: number): number => op & 0x7f
const isContinuousController = (op: number): boolean => ((op >> 7) & 1) === 1

/** A source known at note-on, so its contribution can be folded in up front. */
export const isNoteOnSource = (op: number): boolean =>
  !isContinuousController(op) && (index(op) === VELOCITY || index(op) === KEY_NUMBER)

/** The "no controller" source, which contributes a constant 1. */
const isNoController = (op: number): boolean => !isContinuousController(op) && index(op) === 0

/** `20/96 * log10(x²)` from the spec, rearranged for a 0..1 input. */
const CONCAVE = 40 / 96

const clamp01 = (x: number): number => Math.min(Math.max(x, 0), 1)

/** Transfer curves 0..3: linear, concave, convex, switch. */
export const curve = (type: number, input: number): number => {
  const x = clamp01(input)
  if (type === 1) return clamp01(-CONCAVE * Math.log10(Math.max(1 - x, 1e-6)))
  if (type === 2) return clamp01(1 + CONCAVE * Math.log10(Math.max(x, 1e-6)))
  if (type === 3) return x >= 0.5 ? 1 : 0
  return x
}

/** A note-on source's output, after direction, curve and polarity. */
export const sourceValue = (op: number, key: number, velocity: number): number => {
  const raw = (index(op) === VELOCITY ? velocity : key) / 127
  const directed = ((op >> 8) & 1) === 1 ? 1 - raw : raw
  const shaped = curve((op >> 10) & 0x3f, directed)
  return ((op >> 9) & 1) === 1 ? shaped * 2 - 1 : shaped // bipolar
}

const applies = (m: Modulator): boolean =>
  isNoteOnSource(m.source) &&
  (isNoController(m.amountSource) || isNoteOnSource(m.amountSource)) &&
  (m.destination & 0x8000) === 0 && // a link to another modulator, not a generator
  isAdditiveGen(m.destination)

/**
 * Fold every note-on modulator into the generator set for one voice. Returns
 * `gens` unchanged when nothing applies, which is the overwhelmingly common
 * case, so voices pay nothing for the feature they do not use.
 */
export const modulateGens = (
  gens: GenMap,
  modulators: readonly Modulator[],
  key: number,
  velocity: number,
): GenMap => {
  const live = modulators.filter(applies)
  if (live.length === 0) return gens

  const out = new Map(gens)
  for (const m of live) {
    const scale = isNoController(m.amountSource) ? 1 : sourceValue(m.amountSource, key, velocity)
    const value = m.amount * sourceValue(m.source, key, velocity) * scale
    const applied = m.transform === 2 ? Math.abs(value) : value // 2 = absolute value
    out.set(m.destination, (signedGen(out, m.destination) + Math.round(applied)) & 0xffff)
  }
  return out
}
