/**
 * The public player: load a sound font, pick a program, schedule notes.
 */

import { regionsForNote, regionsOf } from './regions.js'
import type { Region } from './regions.js'
import { parseSoundFont } from './soundfont.js'
import type { SoundFont } from './soundfont.js'
import { decodeSample, startVoice } from './voice.js'
import type { Voice } from './voice.js'

export type SF2Program = {
  /** Index into `SF2Player.programs`, and the argument to `selectProgram`. */
  readonly index: number
  readonly name: string
  /** MIDI bank number; `128` is the percussion bank by convention. */
  readonly bank: number
  /** MIDI program number, 0-127. */
  readonly program: number
}

export type SF2Player = {
  /** Connect this into your graph. */
  readonly output: AudioNode
  /** Every program in the file, ordered by bank then program number. */
  readonly programs: readonly SF2Program[]
  /** The program new notes will use. */
  readonly program: SF2Program
  /** Metadata from the file's INFO block, e.g. `INAM` (name), `ICOP` (copyright). */
  readonly info: ReadonlyMap<string, string>
  /** Switch programs. Sounding notes keep the program they started with. */
  readonly selectProgram: (index: number) => void
  /** Start a note. `time` is on the `AudioContext` clock; default is now. */
  readonly noteOn: (note: number, velocity?: number, time?: number) => void
  /** Release a note started earlier. Ignored if the note is not sounding. */
  readonly noteOff: (note: number, time?: number) => void
  /** Release every sounding note. */
  readonly allNotesOff: (time?: number) => void
  /** Silence everything and release all resources. The player is unusable after. */
  readonly dispose: () => void
}

export type SF2Source = ArrayBuffer | ArrayBufferView | string | URL

const fetchArrayBuffer = async (source: SF2Source): Promise<ArrayBuffer> => {
  if (source instanceof ArrayBuffer) return source
  if (ArrayBuffer.isView(source)) {
    return source.buffer.slice(source.byteOffset, source.byteOffset + source.byteLength) as ArrayBuffer
  }
  const url = String(source)
  const response = await fetch(url)
  if (!response.ok) throw new Error(`failed to load "${url}": ${response.status} ${response.statusText}`)
  return response.arrayBuffer()
}

/** Programs in bank/program order, plus their index back into the hydra. */
const programsOf = (
  sf: SoundFont,
): { readonly programs: readonly SF2Program[]; readonly presetIndices: readonly number[] } => {
  const ordered = sf.presets
    .map((preset, presetIndex) => ({ preset, presetIndex }))
    .sort((a, b) => a.preset.bank - b.preset.bank || a.preset.program - b.preset.program)
  return {
    programs: ordered.map(({ preset }, index) => ({
      index,
      name: preset.name,
      bank: preset.bank,
      program: preset.program,
    })),
    presetIndices: ordered.map(({ presetIndex }) => presetIndex),
  }
}

/**
 * Load a SoundFont 2 file and return a player wired to `context`.
 *
 * ```ts
 * const player = await createSF2Player(context, '/piano.sf2')
 * player.output.connect(context.destination)
 * player.selectProgram(0)
 * player.noteOn(60, 100, context.currentTime + 0.5)
 * player.noteOff(60, context.currentTime + 1.5)
 * ```
 */
export const createSF2Player = async (
  context: BaseAudioContext,
  source: SF2Source,
): Promise<SF2Player> => {
  const sf = parseSoundFont(await fetchArrayBuffer(source))
  const { programs, presetIndices } = programsOf(sf)
  const first = programs[0]
  if (!first) throw new Error('sound font contains no presets')

  const output = context.createGain()
  const buffers = new Map<number, AudioBuffer | undefined>()
  const regions = new Map<number, readonly Region[]>()
  let voices: Voice[] = []
  let current = first
  let disposed = false

  const bufferFor = (sampleId: number): AudioBuffer | undefined => {
    if (!buffers.has(sampleId)) buffers.set(sampleId, decodeSample(context, sf, sampleId))
    return buffers.get(sampleId)
  }

  const regionsFor = (program: SF2Program): readonly Region[] => {
    const cached = regions.get(program.index)
    if (cached) return cached
    const built = regionsOf(sf, presetIndices[program.index] ?? 0)
    regions.set(program.index, built)
    return built
  }

  const at = (time: number | undefined): number => Math.max(time ?? context.currentTime, 0)

  const noteOn = (note: number, velocity = 100, time?: number): void => {
    if (disposed) return
    const when = at(time)
    for (const region of regionsForNote(regionsFor(current), note, velocity)) {
      const sample = sf.samples[region.sampleId]
      const buffer = bufferFor(region.sampleId)
      if (!sample || !buffer) continue
      const voice = startVoice({
        context,
        destination: output,
        buffer,
        sample,
        region,
        note,
        velocity,
        time: when,
      })
      // An exclusive class is a choke group: hi-hats, cuica, and friends.
      if (voice.exclusiveClass !== 0) {
        for (const other of voices) if (other.exclusiveClass === voice.exclusiveClass) other.cut(when)
      }
      voice.onEnded(() => {
        voices = voices.filter((v) => v !== voice)
      })
      voices.push(voice)
    }
  }

  const noteOff = (note: number, time?: number): void => {
    const when = at(time)
    for (const voice of voices) if (voice.note === note) voice.release(when)
  }

  const allNotesOff = (time?: number): void => {
    const when = at(time)
    for (const voice of voices) voice.release(when)
  }

  return {
    output,
    programs,
    info: sf.info,
    get program() {
      return current
    },
    selectProgram: (index) => {
      const program = programs[index]
      if (!program) throw new RangeError(`no program at index ${index} (have ${programs.length})`)
      current = program
    },
    noteOn,
    noteOff,
    allNotesOff,
    dispose: () => {
      disposed = true
      for (const voice of voices) voice.cut(context.currentTime)
      voices = []
      buffers.clear()
      regions.clear()
      output.disconnect()
    },
  }
}
