/**
 * SF2 file parsing: RIFF chunks in, plain immutable records out.
 *
 * Hydra records (`phdr`, `pbag`, ... `shdr`) each end with a terminal entry that
 * only exists to bound the previous record's index range. They are kept in the
 * arrays below for exactly that reason; `presets` / `instruments` / `samples`
 * expose the playable subset.
 */

import type { Chunk } from './riff.js'
import { findList, readName, readRecords, readRiff, requireChunk } from './riff.js'
import type { Modulator } from './modulators.js'

export type PresetHeader = {
  readonly name: string
  readonly program: number
  readonly bank: number
  readonly bagIndex: number
}

export type InstrumentHeader = {
  readonly name: string
  readonly bagIndex: number
}

export type Bag = {
  readonly genIndex: number
  readonly modIndex: number
}

export type Gen = {
  readonly oper: number
  readonly word: number
}

export type SampleHeader = {
  readonly name: string
  readonly start: number
  readonly end: number
  readonly startLoop: number
  readonly endLoop: number
  readonly sampleRate: number
  readonly originalPitch: number
  readonly pitchCorrection: number
  readonly sampleType: number
}

export type SoundFont = {
  readonly info: ReadonlyMap<string, string>
  readonly presets: readonly PresetHeader[]
  readonly instruments: readonly InstrumentHeader[]
  readonly samples: readonly SampleHeader[]
  /** Interleaved 16-bit PCM for every sample, indexed by `SampleHeader` bounds. */
  readonly pcm: Int16Array
  /** Raw hydra tables, terminal records included, for zone resolution. */
  readonly hydra: {
    readonly phdr: readonly PresetHeader[]
    readonly pbag: readonly Bag[]
    readonly pgen: readonly Gen[]
    readonly pmod: readonly Modulator[]
    readonly inst: readonly InstrumentHeader[]
    readonly ibag: readonly Bag[]
    readonly igen: readonly Gen[]
    readonly imod: readonly Modulator[]
  }
}

const readBag = (v: DataView): Bag => ({
  genIndex: v.getUint16(0, true),
  modIndex: v.getUint16(2, true),
})

const readGen = (v: DataView): Gen => ({
  oper: v.getUint16(0, true),
  word: v.getUint16(2, true),
})

const readModulator = (v: DataView): Modulator => ({
  source: v.getUint16(0, true),
  destination: v.getUint16(2, true),
  amount: v.getInt16(4, true),
  amountSource: v.getUint16(6, true),
  transform: v.getUint16(8, true),
})

const readPresetHeader = (v: DataView): PresetHeader => ({
  name: readName(v, 0, 20),
  program: v.getUint16(20, true),
  bank: v.getUint16(22, true),
  bagIndex: v.getUint16(24, true),
})

const readInstrumentHeader = (v: DataView): InstrumentHeader => ({
  name: readName(v, 0, 20),
  bagIndex: v.getUint16(20, true),
})

const readSampleHeader = (v: DataView): SampleHeader => ({
  name: readName(v, 0, 20),
  start: v.getUint32(20, true),
  end: v.getUint32(24, true),
  startLoop: v.getUint32(28, true),
  endLoop: v.getUint32(32, true),
  sampleRate: v.getUint32(36, true),
  originalPitch: v.getUint8(40),
  pitchCorrection: v.getInt8(41),
  sampleType: v.getUint16(44, true),
})

/** 16-bit PCM view over `smpl`, copied only when the chunk is odd-aligned. */
const readPcm = (view: DataView): Int16Array => {
  const count = view.byteLength >> 1
  return view.byteOffset % 2 === 0
    ? new Int16Array(view.buffer, view.byteOffset, count)
    : Int16Array.from({ length: count }, (_, i) => view.getInt16(i * 2, true))
}

/** Textual INFO fields; the binary ones (`ifil`, `irom`) are skipped. */
const TEXT_INFO = new Set(['isng', 'INAM', 'ICRD', 'IENG', 'IPRD', 'ICOP', 'ICMT', 'ISFT'])

const readInfo = (chunks: readonly Chunk[]): ReadonlyMap<string, string> =>
  new Map(
    chunks
      .filter((c) => TEXT_INFO.has(c.id))
      .map((c): readonly [string, string] => [c.id, readName(c.data, 0, c.data.byteLength)]),
  )

/** Parse a `.sf2` file. Throws with a descriptive message on malformed input. */
export const parseSoundFont = (buffer: ArrayBuffer): SoundFont => {
  const root = readRiff(buffer, 'sfbk')
  const info = findList(root.chunks, 'INFO')
  const sdta = findList(root.chunks, 'sdta')
  const pdta = findList(root.chunks, 'pdta')

  const phdr = readRecords(requireChunk(pdta.chunks, 'phdr'), 38, readPresetHeader)
  const pbag = readRecords(requireChunk(pdta.chunks, 'pbag'), 4, readBag)
  const pgen = readRecords(requireChunk(pdta.chunks, 'pgen'), 4, readGen)
  const pmod = readRecords(requireChunk(pdta.chunks, 'pmod'), 10, readModulator)
  const inst = readRecords(requireChunk(pdta.chunks, 'inst'), 22, readInstrumentHeader)
  const ibag = readRecords(requireChunk(pdta.chunks, 'ibag'), 4, readBag)
  const igen = readRecords(requireChunk(pdta.chunks, 'igen'), 4, readGen)
  const imod = readRecords(requireChunk(pdta.chunks, 'imod'), 10, readModulator)
  const shdr = readRecords(requireChunk(pdta.chunks, 'shdr'), 46, readSampleHeader)

  if (phdr.length < 2 || inst.length < 2 || shdr.length < 2) {
    throw new Error('sound font contains no presets')
  }

  return {
    info: readInfo(info.chunks),
    // Drop the terminal ("EOP"/"EOI"/"EOS") records from the playable views.
    presets: phdr.slice(0, -1),
    instruments: inst.slice(0, -1),
    samples: shdr.slice(0, -1),
    pcm: readPcm(requireChunk(sdta.chunks, 'smpl').data),
    hydra: { phdr, pbag, pgen, pmod, inst, ibag, igen, imod },
  }
}
