/**
 * SF2 generator identifiers, their spec defaults, and the merge rules used when
 * a preset zone layers on top of an instrument zone.
 */

export const GEN = {
  startAddrsOffset: 0,
  endAddrsOffset: 1,
  startLoopAddrsOffset: 2,
  endLoopAddrsOffset: 3,
  startAddrsCoarseOffset: 4,
  modLfoToPitch: 5,
  vibLfoToPitch: 6,
  modEnvToPitch: 7,
  initialFilterFc: 8,
  initialFilterQ: 9,
  modLfoToFilterFc: 10,
  modEnvToFilterFc: 11,
  endAddrsCoarseOffset: 12,
  modLfoToVolume: 13,
  pan: 17,
  delayModLFO: 21,
  freqModLFO: 22,
  delayVibLFO: 23,
  freqVibLFO: 24,
  delayModEnv: 25,
  attackModEnv: 26,
  holdModEnv: 27,
  decayModEnv: 28,
  sustainModEnv: 29,
  releaseModEnv: 30,
  keynumToModEnvHold: 31,
  keynumToModEnvDecay: 32,
  delayVolEnv: 33,
  attackVolEnv: 34,
  holdVolEnv: 35,
  decayVolEnv: 36,
  sustainVolEnv: 37,
  releaseVolEnv: 38,
  keynumToVolEnvHold: 39,
  keynumToVolEnvDecay: 40,
  instrument: 41,
  keyRange: 43,
  velRange: 44,
  startLoopAddrsCoarseOffset: 45,
  keynum: 46,
  velocity: 47,
  initialAttenuation: 48,
  endLoopAddrsCoarseOffset: 50,
  coarseTune: 51,
  fineTune: 52,
  sampleID: 53,
  sampleModes: 54,
  scaleTuning: 56,
  exclusiveClass: 57,
  overridingRootKey: 58,
} as const

/** Generator amounts, keyed by operator, stored as raw little-endian words. */
export type GenMap = ReadonlyMap<number, number>

const DEFAULTS: ReadonlyArray<readonly [number, number]> = [
  [GEN.modLfoToPitch, 0],
  [GEN.vibLfoToPitch, 0],
  [GEN.modEnvToPitch, 0],
  [GEN.initialFilterFc, 13500],
  [GEN.initialFilterQ, 0],
  [GEN.modLfoToFilterFc, 0],
  [GEN.modEnvToFilterFc, 0],
  [GEN.modLfoToVolume, 0],
  [GEN.pan, 0],
  [GEN.delayModLFO, -12000],
  [GEN.freqModLFO, 0],
  [GEN.delayVibLFO, -12000],
  [GEN.freqVibLFO, 0],
  [GEN.delayModEnv, -12000],
  [GEN.attackModEnv, -12000],
  [GEN.holdModEnv, -12000],
  [GEN.decayModEnv, -12000],
  // Unlike the volume envelope's centibels, this is a *decrease* in 0.1% units.
  [GEN.sustainModEnv, 0],
  [GEN.releaseModEnv, -12000],
  [GEN.keynumToModEnvHold, 0],
  [GEN.keynumToModEnvDecay, 0],
  [GEN.delayVolEnv, -12000],
  [GEN.attackVolEnv, -12000],
  [GEN.holdVolEnv, -12000],
  [GEN.decayVolEnv, -12000],
  [GEN.sustainVolEnv, 0],
  [GEN.releaseVolEnv, -12000],
  [GEN.keynumToVolEnvHold, 0],
  [GEN.keynumToVolEnvDecay, 0],
  [GEN.keyRange, 127 * 256],
  [GEN.velRange, 127 * 256],
  [GEN.keynum, -1],
  [GEN.velocity, -1],
  [GEN.initialAttenuation, 0],
  [GEN.coarseTune, 0],
  [GEN.fineTune, 0],
  [GEN.sampleModes, 0],
  [GEN.scaleTuning, 100],
  [GEN.exclusiveClass, 0],
  [GEN.overridingRootKey, -1],
]

/** Spec-defined defaults for every generator this player understands. */
export const DEFAULT_GENS: GenMap = new Map(
  DEFAULTS.map(([oper, value]): readonly [number, number] => [oper, value & 0xffff]),
)

/**
 * Generators a preset zone may not offset: ranges, indices, and anything that
 * addresses sample data. Everything else is additive (§9.4 of the SF2 spec).
 */
const ABSOLUTE = new Set<number>([
  GEN.startAddrsOffset,
  GEN.endAddrsOffset,
  GEN.startLoopAddrsOffset,
  GEN.endLoopAddrsOffset,
  GEN.startAddrsCoarseOffset,
  GEN.endAddrsCoarseOffset,
  GEN.startLoopAddrsCoarseOffset,
  GEN.endLoopAddrsCoarseOffset,
  GEN.instrument,
  GEN.keyRange,
  GEN.velRange,
  GEN.keynum,
  GEN.velocity,
  GEN.sampleID,
  GEN.sampleModes,
  GEN.exclusiveClass,
  GEN.overridingRootKey,
])

/** Whether a generator takes an offset, rather than being a range or an index. */
export const isAdditiveGen = (oper: number): boolean => !ABSOLUTE.has(oper)

const toSigned = (word: number): number => (word << 16) >> 16

/** Signed generator amount, or `fallback` when absent. */
export const signedGen = (gens: GenMap, oper: number, fallback = 0): number => {
  const word = gens.get(oper) ?? DEFAULT_GENS.get(oper)
  return word === undefined ? fallback : toSigned(word)
}

/** Unsigned generator amount (indices), or `fallback` when absent. */
export const wordGen = (gens: GenMap, oper: number, fallback = 0): number =>
  gens.get(oper) ?? DEFAULT_GENS.get(oper) ?? fallback

/** `[low, high]` byte pair of a range generator. */
export const rangeGen = (gens: GenMap, oper: number): readonly [number, number] => {
  const word = wordGen(gens, oper, 127 * 256)
  return [word & 0xff, (word >> 8) & 0xff]
}

/** Merge instrument-level generators with the preset-level layer above them. */
export const mergeGens = (instrument: GenMap, preset: GenMap): GenMap => {
  const merged = new Map(instrument)
  for (const [oper, word] of preset) {
    if (ABSOLUTE.has(oper)) continue
    merged.set(oper, (toSigned(merged.get(oper) ?? DEFAULT_GENS.get(oper) ?? 0) + toSigned(word)) & 0xffff)
  }
  return merged
}

/** Overlap of two inclusive `[low, high]` ranges, or `undefined` when disjoint. */
export const intersect = (
  a: readonly [number, number],
  b: readonly [number, number],
): readonly [number, number] | undefined => {
  const lo = Math.max(a[0], b[0])
  const hi = Math.min(a[1], b[1])
  return lo <= hi ? [lo, hi] : undefined
}

/** Timecents to seconds. `-12000` and below is the spec's "instant". */
export const timecentsToSeconds = (timecents: number): number =>
  timecents <= -12000 ? 0 : Math.pow(2, timecents / 1200)

/** Centibels of attenuation to a linear gain. */
export const centibelsToGain = (centibels: number): number =>
  centibels <= 0 ? 1 : centibels >= 1000 ? 0 : Math.pow(10, -centibels / 200)

/** Absolute cents to Hz (`6900 cents` = 440 Hz). */
export const centsToHz = (cents: number): number => 8.176 * Math.pow(2, cents / 1200)

/**
 * Velocity to a linear gain.
 *
 * This is the spec's default velocity-to-attenuation modulator (960 cB,
 * concave, decreasing) written out: `960 * -(40/96) * log10(v/127)` centibels
 * of attenuation is `10 ^ (-cB/200)` = `(v/127)²` of gain, exactly.
 */
export const velocityToGain = (velocity: number): number => (velocity / 127) ** 2
