/**
 * Zone flattening: a preset is a two-level tree (preset zones -> instrument
 * zones -> samples). This collapses it into a flat list of regions, each one a
 * fully merged generator set that a single note can trigger directly.
 */

import { GEN, intersect, mergeGens, rangeGen } from './generators.js'
import type { GenMap } from './generators.js'
import type { Modulator } from './modulators.js'
import type { Bag, Gen, SoundFont } from './soundfont.js'

export type Region = {
  readonly gens: GenMap
  /** Note-on modulators from this zone, instrument level then preset level. */
  readonly modulators: readonly Modulator[]
  readonly sampleId: number
  readonly keyRange: readonly [number, number]
  readonly velRange: readonly [number, number]
}

type Zone = {
  readonly gens: GenMap
  readonly mods: readonly Modulator[]
  /** `instrument` (preset zones) or `sampleID` (instrument zones), if present. */
  readonly target: number | undefined
}

/** Half-open `[genIndex, nextGenIndex)` slice belonging to bag `i`. */
const gensOfBag = (bags: readonly Bag[], gens: readonly Gen[], i: number): GenMap => {
  const from = bags[i]?.genIndex ?? 0
  const to = bags[i + 1]?.genIndex ?? gens.length
  // A later duplicate wins, which is what Map's constructor does for us.
  return new Map(gens.slice(from, to).map((g): readonly [number, number] => [g.oper, g.word]))
}

const modsOfBag = (
  bags: readonly Bag[],
  mods: readonly Modulator[],
  i: number,
): readonly Modulator[] => mods.slice(bags[i]?.modIndex ?? 0, bags[i + 1]?.modIndex ?? mods.length)

/**
 * Zones of one preset/instrument. A leading zone that lacks the terminating
 * generator is a *global* zone: its generators and modulators become defaults
 * for its siblings.
 */
const readZones = (
  bags: readonly Bag[],
  gens: readonly Gen[],
  mods: readonly Modulator[],
  bagFrom: number,
  bagTo: number,
  terminator: number,
): readonly Zone[] => {
  const raw = Array.from({ length: Math.max(0, bagTo - bagFrom) }, (_, i) => {
    const map = gensOfBag(bags, gens, bagFrom + i)
    return { gens: map, mods: modsOfBag(bags, mods, bagFrom + i), target: map.get(terminator) }
  })
  const global = raw[0]?.target === undefined ? raw[0] : undefined
  const zones = global ? raw.slice(1) : raw
  return global
    ? zones.map((z) => ({
        ...z,
        gens: new Map([...global.gens, ...z.gens]),
        mods: [...global.mods, ...z.mods],
      }))
    : zones
}

/**
 * Zones of record `index`, whose bag range runs up to the next record's. The
 * terminal record has no zones of its own, so it is out of range too.
 */
const zonesOfRecord = (
  headers: readonly { readonly bagIndex: number }[],
  bags: readonly Bag[],
  gens: readonly Gen[],
  mods: readonly Modulator[],
  index: number,
  terminator: number,
): readonly Zone[] => {
  const header = headers[index]
  const next = headers[index + 1]
  if (!header || !next) return []
  return readZones(bags, gens, mods, header.bagIndex, next.bagIndex, terminator)
}

const presetZones = (sf: SoundFont, presetIndex: number): readonly Zone[] =>
  zonesOfRecord(
    sf.hydra.phdr,
    sf.hydra.pbag,
    sf.hydra.pgen,
    sf.hydra.pmod,
    presetIndex,
    GEN.instrument,
  )

const instrumentZones = (sf: SoundFont, instrumentIndex: number): readonly Zone[] =>
  zonesOfRecord(
    sf.hydra.inst,
    sf.hydra.ibag,
    sf.hydra.igen,
    sf.hydra.imod,
    instrumentIndex,
    GEN.sampleID,
  )

/**
 * Every region of a preset, flattened. Preset-level generators are added to the
 * instrument's; key and velocity ranges intersect, and a region whose ranges do
 * not overlap is dropped.
 */
export const regionsOf = (sf: SoundFont, presetIndex: number): readonly Region[] =>
  presetZones(sf, presetIndex).flatMap((preset) =>
    preset.target === undefined || preset.target >= sf.instruments.length
      ? []
      : instrumentZones(sf, preset.target).flatMap((zone): Region[] => {
          const keyRange = intersect(
            rangeGen(zone.gens, GEN.keyRange),
            rangeGen(preset.gens, GEN.keyRange),
          )
          const velRange = intersect(
            rangeGen(zone.gens, GEN.velRange),
            rangeGen(preset.gens, GEN.velRange),
          )
          const sampleId = zone.target
          if (!keyRange || !velRange || sampleId === undefined || sampleId >= sf.samples.length) {
            return []
          }
          return [
            {
              gens: mergeGens(zone.gens, preset.gens),
              modulators: [...zone.mods, ...preset.mods],
              sampleId,
              keyRange,
              velRange,
            },
          ]
        }),
  )

export const matchesNote = (region: Region, note: number, velocity: number): boolean =>
  note >= region.keyRange[0] &&
  note <= region.keyRange[1] &&
  velocity >= region.velRange[0] &&
  velocity <= region.velRange[1]

/** Regions triggered by one note-on, in file order (layers all sound together). */
export const regionsForNote = (
  regions: readonly Region[],
  note: number,
  velocity: number,
): readonly Region[] => regions.filter((r) => matchesNote(r, note, velocity))
