/**
 * One region + one note = one voice. Everything is scheduled against the audio
 * clock via `AudioParam` automation and `start(when)`, so a voice is
 * sample-accurate regardless of when JavaScript got around to building it.
 *
 * Modulation rides on the two a-rate params Web Audio already expresses in
 * cents — `AudioBufferSourceNode.detune` and `BiquadFilterNode.detune` — which
 * is the same unit SF2 uses, so pitch and filter routing need no conversion.
 */

import {
  GEN,
  centibelsToGain,
  centsToHz,
  signedGen,
  timecentsToSeconds,
  velocityToGain,
  wordGen,
} from './generators.js'
import type { GenMap } from './generators.js'
import { modulateGens } from './modulators.js'
import type { Region } from './regions.js'
import type { SampleHeader, SoundFont } from './soundfont.js'

/** Floor for exponential ramps, which cannot reach zero. ~-100 dB. */
const SILENCE = 1e-5

/** Shortest fade used when a voice is cut, long enough to avoid a click. */
const MIN_FADE = 0.005

/** `initialFilterFc` at or above this means the low-pass is bypassed. */
const NO_FILTER_CENTS = 13500

export type Voice = {
  readonly note: number
  readonly exclusiveClass: number
  /** Enter the release phase at `time`; resolves to the time the voice ends. */
  readonly release: (time: number) => number
  /** Cut the voice short with a click-free fade, ignoring its release time. */
  readonly cut: (time: number) => number
  readonly onEnded: (fn: () => void) => void
}

type Envelope = {
  readonly delay: number
  readonly attack: number
  readonly hold: number
  readonly decay: number
  /** Level held after decay, as a fraction of the peak. */
  readonly sustain: number
  readonly release: number
}

/** `cancelAndHoldAtTime` with a graceful fallback for older engines. */
const holdValueAt = (param: AudioParam, time: number): void => {
  const withHold = param as AudioParam & { cancelAndHoldAtTime?: (t: number) => void }
  if (typeof withHold.cancelAndHoldAtTime === 'function') withHold.cancelAndHoldAtTime(time)
  else param.cancelScheduledValues(time)
}

const keyScale = (gens: GenMap, oper: number, key: number): number =>
  Math.pow(2, (signedGen(gens, oper) * (60 - key)) / 1200)

/**
 * Volume envelope. The attack is linear in amplitude and the decay is linear in
 * decibels, matching §8.1.2 of the SF2 spec; `decay` is specified as the time
 * for a full 100 dB fall, so reaching sustain takes a proportional slice of it.
 */
const volumeEnvelopeOf = (gens: GenMap, key: number): Envelope => {
  const sustainCb = Math.min(Math.max(signedGen(gens, GEN.sustainVolEnv), 0), 1000)
  return {
    delay: timecentsToSeconds(signedGen(gens, GEN.delayVolEnv)),
    attack: timecentsToSeconds(signedGen(gens, GEN.attackVolEnv)),
    hold: timecentsToSeconds(signedGen(gens, GEN.holdVolEnv)) * keyScale(gens, GEN.keynumToVolEnvHold, key),
    decay:
      timecentsToSeconds(signedGen(gens, GEN.decayVolEnv)) *
      keyScale(gens, GEN.keynumToVolEnvDecay, key) *
      (sustainCb / 1000),
    sustain: centibelsToGain(sustainCb),
    release: timecentsToSeconds(signedGen(gens, GEN.releaseVolEnv)),
  }
}

/**
 * Modulation envelope. Its `sustain` generator is a *decrease* in 0.1% units of
 * the peak, not the volume envelope's centibels of attenuation — a difference
 * the spec is easy to misread.
 */
export const modEnvelopeOf = (gens: GenMap, key: number): Envelope => {
  const decrease = Math.min(Math.max(signedGen(gens, GEN.sustainModEnv), 0), 1000) / 1000
  return {
    delay: timecentsToSeconds(signedGen(gens, GEN.delayModEnv)),
    attack: timecentsToSeconds(signedGen(gens, GEN.attackModEnv)),
    hold: timecentsToSeconds(signedGen(gens, GEN.holdModEnv)) * keyScale(gens, GEN.keynumToModEnvHold, key),
    decay:
      timecentsToSeconds(signedGen(gens, GEN.decayModEnv)) *
      keyScale(gens, GEN.keynumToModEnvDecay, key) *
      decrease,
    sustain: 1 - decrease,
    release: timecentsToSeconds(signedGen(gens, GEN.releaseModEnv)),
  }
}

const scheduleVolumeEnvelope = (gain: AudioParam, at: number, level: number, env: Envelope): void => {
  const peak = Math.max(level, SILENCE) // exponential ramps cannot start from zero
  const attackStart = at + env.delay
  const attackEnd = attackStart + env.attack
  const decayStart = attackEnd + env.hold
  if (env.delay > 0) gain.setValueAtTime(SILENCE, at)
  if (env.attack > 0) {
    gain.setValueAtTime(SILENCE, attackStart)
    gain.linearRampToValueAtTime(peak, attackEnd)
  } else {
    gain.setValueAtTime(peak, attackStart)
  }
  if (env.decay > 0 && env.sustain < 1) {
    if (decayStart > attackEnd) gain.setValueAtTime(peak, decayStart)
    gain.exponentialRampToValueAtTime(Math.max(peak * env.sustain, SILENCE), decayStart + env.decay)
  }
}

/**
 * Modulation envelope on a signed destination (cents of pitch or cutoff).
 * Linear ramps throughout: the value legitimately crosses and rests at zero,
 * which an exponential ramp cannot express.
 */
const scheduleModEnvelope = (param: AudioParam, at: number, depth: number, env: Envelope): void => {
  const attackStart = at + env.delay
  const attackEnd = attackStart + env.attack
  const decayStart = attackEnd + env.hold
  if (env.delay > 0) param.setValueAtTime(0, at)
  if (env.attack > 0) {
    param.setValueAtTime(0, attackStart)
    param.linearRampToValueAtTime(depth, attackEnd)
  } else {
    param.setValueAtTime(depth, attackStart)
  }
  if (env.decay > 0 && env.sustain < 1) {
    if (decayStart > attackEnd) param.setValueAtTime(depth, decayStart)
    param.linearRampToValueAtTime(depth * env.sustain, decayStart + env.decay)
  }
}

/** Pitch ratio for `key`, folding in root key, tuning and sample rate mismatch. */
const playbackRate = (
  gens: GenMap,
  sample: SampleHeader,
  key: number,
  contextRate: number,
): number => {
  const overridingRoot = signedGen(gens, GEN.overridingRootKey)
  const root = overridingRoot >= 0 ? overridingRoot : sample.originalPitch
  const cents =
    (key - root) * signedGen(gens, GEN.scaleTuning) +
    signedGen(gens, GEN.coarseTune) * 100 +
    signedGen(gens, GEN.fineTune) +
    sample.pitchCorrection
  return Math.pow(2, cents / 1200) * (sample.sampleRate / contextRate)
}

/**
 * Generator-adjusted sample address, clamped into the sample's own bounds.
 *
 * The clamp is not paranoia: real sound fonts ship loop points a frame or two
 * outside `[start, end]`, and an unclamped `loopEnd` past the buffer silences
 * the voice.
 */
export const sampleAddress = (
  gens: GenMap,
  base: number,
  fine: number,
  coarse: number,
  sample: SampleHeader,
): number =>
  Math.min(
    Math.max(base + signedGen(gens, fine) + signedGen(gens, coarse) * 32768, sample.start),
    sample.end,
  )

/**
 * Copy one sample's PCM into an `AudioBuffer` tagged at the context's own rate.
 * Pitch (including the rate mismatch) is handled entirely by `playbackRate`, so
 * loop points stay in a single, predictable time base.
 */
export const decodeSample = (
  context: BaseAudioContext,
  sf: SoundFont,
  sampleId: number,
): AudioBuffer | undefined => {
  const sample = sf.samples[sampleId]
  if (!sample) return undefined
  const length = sample.end - sample.start
  if (length <= 0) return undefined
  const buffer = context.createBuffer(1, length, context.sampleRate)
  const channel = buffer.getChannelData(0)
  for (let i = 0; i < length; i++) channel[i] = (sf.pcm[sample.start + i] ?? 0) / 32768
  return buffer
}

export type VoiceOptions = {
  readonly context: BaseAudioContext
  readonly destination: AudioNode
  readonly buffer: AudioBuffer
  readonly sample: SampleHeader
  readonly region: Region
  readonly note: number
  readonly velocity: number
  readonly time: number
}

export const startVoice = (options: VoiceOptions): Voice => {
  const { context, destination, buffer, sample, region, note, velocity, time } = options
  const forcedKey = signedGen(region.gens, GEN.keynum)
  const forcedVel = signedGen(region.gens, GEN.velocity)
  const key = forcedKey >= 0 ? forcedKey : note
  const vel = forcedVel >= 0 ? forcedVel : velocity

  // Note-on modulators (velocity -> cutoff and friends) fold into the
  // generators before anything reads them.
  const gens = modulateGens(region.gens, region.modulators, key, vel)

  const env = volumeEnvelopeOf(gens, key)
  const peak = centibelsToGain(signedGen(gens, GEN.initialAttenuation)) * velocityToGain(vel)

  const modEnvToPitch = signedGen(gens, GEN.modEnvToPitch)
  const modEnvToFilter = signedGen(gens, GEN.modEnvToFilterFc)
  const modLfoToPitch = signedGen(gens, GEN.modLfoToPitch)
  const modLfoToFilter = signedGen(gens, GEN.modLfoToFilterFc)
  const modLfoToVolume = signedGen(gens, GEN.modLfoToVolume)
  const vibLfoToPitch = signedGen(gens, GEN.vibLfoToPitch)

  const gain = context.createGain()
  const panner = context.createStereoPanner()
  panner.pan.value = Math.min(Math.max(signedGen(gens, GEN.pan) / 500, -1), 1)

  // 13500 cents (~19.9 kHz) is the spec's "wide open" default: no filter at all,
  // rather than a biquad parked next to Nyquist where it would ring. A filter is
  // still needed when something modulates the cutoff.
  const cutoffCents = signedGen(gens, GEN.initialFilterFc)
  const filterModulated = modEnvToFilter !== 0 || modLfoToFilter !== 0
  const filter =
    cutoffCents < NO_FILTER_CENTS || filterModulated ? context.createBiquadFilter() : undefined
  if (filter) {
    filter.type = 'lowpass'
    filter.frequency.value = Math.min(Math.max(centsToHz(cutoffCents), 20), context.sampleRate * 0.45)
    filter.Q.value = signedGen(gens, GEN.initialFilterQ) / 10 // centibels -> dB
  }

  const source = context.createBufferSource()
  source.buffer = buffer
  source.playbackRate.value = playbackRate(gens, sample, key, context.sampleRate)

  const rate = context.sampleRate
  const startAt = sampleAddress(gens, sample.start, GEN.startAddrsOffset, GEN.startAddrsCoarseOffset, sample)
  const endAt = sampleAddress(gens, sample.end, GEN.endAddrsOffset, GEN.endAddrsCoarseOffset, sample)
  const looping = (wordGen(gens, GEN.sampleModes) & 3) !== 0
  if (looping) {
    source.loop = true
    source.loopStart =
      (sampleAddress(gens, sample.startLoop, GEN.startLoopAddrsOffset, GEN.startLoopAddrsCoarseOffset, sample) -
        sample.start) /
      rate
    source.loopEnd =
      (sampleAddress(gens, sample.endLoop, GEN.endLoopAddrsOffset, GEN.endLoopAddrsCoarseOffset, sample) -
        sample.start) /
      rate
  }

  source.connect(filter ?? gain)
  filter?.connect(gain)
  gain.connect(panner)
  panner.connect(destination)

  scheduleVolumeEnvelope(gain.gain, time, peak, env)

  // `start`'s offset and duration are in buffer seconds; wall-clock length
  // therefore scales down by the playback rate.
  const offset = (startAt - sample.start) / rate
  const bufferSeconds = (endAt - startAt) / rate
  if (looping) source.start(time, offset) // runs until released
  else source.start(time, offset, bufferSeconds) // one-shot, ends on its own

  let endsAt = looping ? Infinity : time + bufferSeconds / source.playbackRate.value

  // --- modulation envelope, straight onto the cents params ---
  const modulated: AudioParam[] = []
  const modEnv = modEnvToPitch !== 0 || modEnvToFilter !== 0 ? modEnvelopeOf(gens, key) : undefined
  if (modEnv) {
    if (modEnvToPitch !== 0) modulated.push(source.detune)
    if (modEnvToFilter !== 0 && filter) modulated.push(filter.detune)
    if (modEnvToPitch !== 0) scheduleModEnvelope(source.detune, time, modEnvToPitch, modEnv)
    if (modEnvToFilter !== 0 && filter) {
      scheduleModEnvelope(filter.detune, time, modEnvToFilter, modEnv)
    }
  }

  // --- low frequency oscillators ---
  const oscillators: OscillatorNode[] = []
  const gains: GainNode[] = []
  const startLfo = (
    freqOper: number,
    delayOper: number,
    targets: ReadonlyArray<{ readonly param: AudioParam; readonly depth: number }>,
  ): void => {
    const live = targets.filter((t) => t.depth !== 0)
    if (live.length === 0) return
    const startsAt = time + timecentsToSeconds(signedGen(gens, delayOper))
    if (startsAt >= endsAt) return
    const osc = context.createOscillator()
    osc.type = 'sine'
    osc.frequency.value = centsToHz(signedGen(gens, freqOper))
    for (const target of live) {
      const depth = context.createGain()
      depth.gain.value = target.depth
      osc.connect(depth)
      depth.connect(target.param)
      gains.push(depth)
    }
    // Silent until it starts, which is exactly what the LFO delay means.
    osc.start(startsAt)
    if (Number.isFinite(endsAt)) osc.stop(endsAt)
    oscillators.push(osc)
  }

  startLfo(GEN.freqModLFO, GEN.delayModLFO, [
    { param: source.detune, depth: modLfoToPitch },
    ...(filter ? [{ param: filter.detune, depth: modLfoToFilter }] : []),
    // Centibels of tremolo, linearised around the envelope's current level.
    // Real fonts use a fraction of a dB here, where the error is negligible.
    { param: gain.gain, depth: peak * (1 - centibelsToGain(Math.abs(modLfoToVolume))) },
  ])
  startLfo(GEN.freqVibLFO, GEN.delayVibLFO, [{ param: source.detune, depth: vibLfoToPitch }])

  const fadeOut = (at: number, seconds: number): number => {
    const from = Math.max(at, time)
    const until = from + seconds
    if (until >= endsAt) return endsAt
    holdValueAt(gain.gain, from)
    gain.gain.setTargetAtTime(SILENCE, from, Math.max(seconds, MIN_FADE) / 5)
    // The modulation envelope releases on its own schedule, back to no offset.
    if (modEnv) {
      for (const param of modulated) {
        holdValueAt(param, from)
        param.linearRampToValueAtTime(0, from + Math.max(modEnv.release, MIN_FADE))
      }
    }
    source.stop(until)
    for (const osc of oscillators) osc.stop(until)
    endsAt = until
    return until
  }

  return {
    note,
    exclusiveClass: wordGen(gens, GEN.exclusiveClass),
    release: (at) => fadeOut(at, Math.max(env.release, MIN_FADE)),
    cut: (at) => fadeOut(at, MIN_FADE),
    onEnded: (fn) => {
      source.onended = () => {
        source.disconnect()
        filter?.disconnect()
        gain.disconnect()
        panner.disconnect()
        for (const osc of oscillators) osc.disconnect()
        for (const g of gains) g.disconnect()
        fn()
      }
    },
  }
}
