import { createSF2Player, SF2Player, SF2Program } from '@gwegash/sf2-player'
import { Instrument, InstArgs } from './instruments'

class Sf2Player extends Instrument {

  static def = { name: "sf2" }
  url: string
  player: SF2Player
  programMap: Record<string, number> //todo speedup search with this
  programsEl: HTMLElement
  programEls: HTMLElement[]

  constructor(context: AudioContext, parentEl: Element, name: string) {
    super(context, parentEl, name)

    this.webAudioNodes.gainNode = context.createGain()
    this.webAudioNodes.gainNode.gain.value = 1.0
    this.outputNode = this.webAudioNodes.gainNode

    this.setupUI()
  }

  async setup({url, program}: InstArgs) {
    if(url != this.url){

      this.player = await createSF2Player(this.audioContext, url)
      this.webAudioNodes.player = this.player
      this.url = url
      this.player.output.connect(this.webAudioNodes.gainNode)
      this.programMap = Object.fromEntries(this.player.programs.map(entry => [entry.name, entry.index]))
      this.resetProgramEl()
    }

    if(program != "" && this.programMap && this.programMap[program]){
      this.setProgram(program)
    }

    return this
  }

  setProgram(programName: string): void {
    this.player.selectProgram(this.programMap[programName])
    this.programEls[this.player.program.index]
  }

  setupProgramElement(program: SF2Program): HTMLElement{
    const programEl = document.createElement("div")
    programEl.className = "sf2-program"
    programEl.innerText = program.name
    programEl.addEventListener("mouseup", (a) => {
      this.setProgram(program.name)
    })
    return programEl
  }

  play(note, startTime, dur) {
    // Schedule against the audio clock: both notes land on an exact frame.
    console.log("playing")
    if(dur > 0){
      this.player?.noteOn(note, 100, startTime)
      this.player?.noteOff(note, startTime + dur)
    }
    else if (dur < 0){
      this.player?.noteOn(note, 100, startTime)
    }
    else if (dur == 0){
      this.player?.noteOff(note, startTime)
    }
  }

  resetProgramEl(){
    this.programEls = this.player.programs.map(program => this.setupProgramElement(program))
    this.programsEl.replaceChildren(...this.programEls)
  }

  setupUI() {
    this.programsEl = document.createElement("div")
    this.programsEl.className = "sf2-programs"
    this.el.appendChild(this.programsEl)
  }
}

export { Sf2Player }
