//This module listens to MIDI messages, and forwards events onto handlers that are registered with it.
//It also owns the outward direction: which MIDI outputs exist, and how a time on trane's
//audio clock becomes a timestamp Web MIDI can schedule against.

const CC = 0xb0
const NOTE_ON = 0x90
const cc_registrations = {
  //cc to callback //TODO make this use the input too they will clash if someone has multiple midi controllers
}

const note_registrations = {}

/*
 * A fixed trim, in milliseconds, on every outgoing timestamp. getOutputTimestamp already
 * accounts for the browser's own output latency, but not for whatever the MIDI interface
 * and the receiving device add on top. Reach for this if hardware sits consistently early
 * (make it negative) or late (positive) against the audio.
 */
const MIDI_OFFSET_MS = 0

let midi: MIDIAccess
let midiReady: Promise<MIDIAccess | undefined> //memoised, so the permission prompt happens once

const outputListeners: Array<() => void> = []

let registeringFunction //the current function trying to get an assignment to the next cc parameter

//Requesting access prompts the user, so only call this off the back of something they clicked.
function init(): Promise<MIDIAccess | undefined> {
  if (!midiReady) {
    midiReady = navigator.requestMIDIAccess().then(
      (midiAccess) => {
        console.log("MIDI ready!")
        midi = midiAccess // store in the global (in real usage, would probably keep in an object instance)
        window.midi = midi
        listenToMidiMessages(midi, 0)
        //A device plugged in later needs listening to as well, and the outputs list redrawing
        midi.onstatechange = () => {
          listenToMidiMessages(midi, 0)
          outputListeners.forEach((listener) => listener())
        }
        return midiAccess
      },
      (msg) => {
        console.error(`Failed to get MIDI access - ${msg}`)
        midiReady = undefined //let the next caller try again
        return undefined
      },
    )
  }
  return midiReady
}

function registerCC(callback) {
  registeringFunction = callback
  if (!midi) {
    init()
  }
}

function getOutputs(): MIDIOutput[] {
  return midi ? [...midi.outputs.values()] : []
}

function onOutputsChanged(listener: () => void) {
  outputListeners.push(listener)
}

function offOutputsChanged(listener: () => void) {
  const i = outputListeners.indexOf(listener)
  if (i >= 0) {
    outputListeners.splice(i, 1)
  }
}

/*
 * Web MIDI schedules against performance.now() milliseconds, but everything in trane is
 * scheduled against the audio clock. getOutputTimestamp hands back a matched pair of the
 * two -- the context time of the frame currently reaching the speakers, and the wall-clock
 * moment it got there -- so this lines MIDI up with what is audible rather than with what
 * has merely been queued.
 *
 * The two clocks run off different crystals and drift apart over a set, so re-sample the
 * pair on every call instead of caching an offset taken at startup.
 */
function audioTimeToMidiTime(context: AudioContext, audioTime: number): number {
  const { contextTime, performanceTime } = context.getOutputTimestamp()
  if (!contextTime || !performanceTime) {
    //Nothing has been rendered yet, so fall back to the live clocks and wear the latency
    return (
      performance.now() +
      (audioTime - context.currentTime) * 1000 +
      MIDI_OFFSET_MS
    )
  }
  return performanceTime + (audioTime - contextTime) * 1000 + MIDI_OFFSET_MS
}

function onMIDIMessage(event) {
  if (event.data[0] === CC) {
    if (registeringFunction != undefined) {
      console.log("registered CC event")
      cc_registrations[event.data[1]] = registeringFunction
      registeringFunction = undefined //clear this, for the next registration
    } else if (cc_registrations[event.data[1]]) {
      //we have a function registered
      cc_registrations[event.data[1]](event.data[2]) //call the function
    }
  } else if (event.data[0] === NOTE_ON) {
    Object.values(note_registrations).forEach((note_registration) => {
      const dur = event.data[2] > 0 ? -1 : 0
      note_registration.play(
        event.data[1],
        note_registration.audioContext.currentTime,
        dur,
      )
    })
  }
}

function listenToMidiMessages(midiAccess, indexOfPort) {
  midiAccess.inputs.forEach((entry) => {
    entry.onmidimessage = onMIDIMessage
  })
}

function registerMidiNoteInput(toName: string, to: Instrument) {
  note_registrations[toName] = to
}

function deregisterMidiNoteInput(toName: string) {
  delete note_registrations[toName]
}

export {
  init,
  registerCC,
  registerMidiNoteInput,
  deregisterMidiNoteInput,
  getOutputs,
  onOutputsChanged,
  offOutputsChanged,
  audioTimeToMidiTime,
}
